<style>
    .pumk-monitor{max-width:1260px;margin:0 auto;color:#0f172a}.pumk-monitor h1{margin:0;font-size:clamp(26px,3vw,36px);font-weight:750}.pumk-monitor p{line-height:1.6}.pumk-monitor .intro{margin:5px 0 22px;color:#64748b}.pumk-monitor .notice,.pumk-monitor .warning{border:1px solid #93c5fd;border-radius:9px;background:#eff6ff;padding:12px 16px;color:#1e40af}.pumk-monitor .warning{border-color:#f59e0b;background:#fffbeb;color:#92400e}.pumk-monitor .monitor-tabs{display:flex;gap:8px;margin:20px 0;border-bottom:1px solid #cbd5e1}.pumk-monitor .monitor-tabs a{border:1px solid transparent;border-radius:8px 8px 0 0;padding:11px 16px;color:#334155;text-decoration:none;font-weight:700}.pumk-monitor .monitor-tabs a.active{border-color:#cbd5e1;border-bottom-color:#fff;background:#fff;color:#1d4ed8}.pumk-monitor .grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px;margin:22px 0}.pumk-monitor .metric,.pumk-monitor .panel{border:1px solid #cbd5e1;border-radius:10px;background:#fff;box-shadow:0 2px 5px #0f172a0d}.pumk-monitor .metric{padding:18px}.pumk-monitor .metric span{display:block;color:#475569;font-size:13px}.pumk-monitor .metric strong{display:block;margin-top:10px;font-size:clamp(20px,2.2vw,29px);overflow-wrap:anywhere}.pumk-monitor .panel{margin-top:18px;padding:20px}.pumk-monitor h2{margin:0 0 15px;font-size:20px}.pumk-monitor .actions{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}.pumk-monitor a.button,.pumk-monitor button.button{display:inline-flex;align-items:center;min-height:40px;border:1px solid #1d4ed8;border-radius:7px;background:#1d4ed8;padding:8px 15px;color:#fff;text-decoration:none;font:600 13px Poppins,sans-serif;cursor:pointer}.pumk-monitor a.button.secondary{background:#fff;color:#1d4ed8}.pumk-monitor .table-wrap{overflow:auto}.pumk-monitor table{width:100%;border-collapse:collapse;font-size:13px}.pumk-monitor th,.pumk-monitor td{border:1px solid #cbd5e1;padding:10px;text-align:left;vertical-align:top}.pumk-monitor th{background:#e2e8f0}.pumk-monitor .number{text-align:right;font-variant-numeric:tabular-nums}.pumk-monitor .muted{color:#64748b}.pumk-monitor .search,.pumk-monitor .year-filter{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.pumk-monitor .search input{flex:1;min-width:220px;border:1px solid #94a3b8;border-radius:7px;padding:8px 12px;font:inherit}.pumk-monitor select{min-width:150px;border:1px solid #94a3b8;border-radius:7px;background:#fff;padding:8px 12px;font:inherit}.pumk-monitor .pages{margin-top:18px}.pumk-monitor .status-tabs{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}.pumk-monitor .status-tabs a{border:1px solid #94a3b8;border-radius:7px;padding:8px 13px;color:#334155;text-decoration:none;font-weight:600}.pumk-monitor .status-tabs a.active{border-color:#1d4ed8;background:#1d4ed8;color:#fff}.pumk-monitor .status-badge{display:inline-flex;border-radius:999px;padding:4px 8px;background:#e2e8f0;font-size:11px;font-weight:700}.pumk-monitor .status-badge.lunas{background:#dcfce7;color:#166534}.pumk-monitor .status-badge.aktif{background:#dbeafe;color:#1e40af}@media(max-width:900px){.pumk-monitor .grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:550px){.pumk-monitor .grid{grid-template-columns:1fr}.pumk-monitor .monitor-tabs{flex-direction:column;border:0}.pumk-monitor .monitor-tabs a{border-radius:8px;border:1px solid #cbd5e1}}
</style>
